STORAGE_SERVICE_SKU = 'USL-PRZECHOWANIE'
STORAGE_ITEM_DESCRIPTION = 'Przechowanie zimowe'


def move_prices_to_order_items(apps, schema_editor):
    """Cena przechowania przenosi sie z rezerwacji na zlecenie jako pozycja.

    Jedna pozycja na zlecenie i cene (ilosc = liczba sztuk), z pominieciem anulowanych
    pobytow i zlecen, ktore pozycje przechowania juz maja. Informacja o wplatach przepada -
    od teraz rozliczenie jest na zleceniu.
    """
    StorageBooking = apps.get_model('storage', 'StorageBooking')
    RepairOrder = apps.get_model('orders', 'RepairOrder')
    RepairOrderItem = apps.get_model('orders', 'RepairOrderItem')
    Part = apps.get_model('inventory', 'Part')

    storage_part = Part.objects.filter(sku=STORAGE_SERVICE_SKU).first()
    groups = Counter(
        StorageBooking.objects.exclude(status='cancelled').values_list('repair_order_id', 'price')
    )
    touched = set()
    for (order_id, price), count in groups.items():
        existing = RepairOrderItem.objects.filter(repair_order_id=order_id)
        if storage_part is not None and existing.filter(part=storage_part).exists():
            continue
        if existing.filter(description=STORAGE_ITEM_DESCRIPTION).exists():
            continue
        order = RepairOrder.objects.get(pk=order_id)
        item = RepairOrderItem.objects.create(
            repair_order=order, part=storage_part, item_type='service',
            description=storage_part.name if storage_part else STORAGE_ITEM_DESCRIPTION,
            quantity=Decimal(count), unit_price=price,
        )
        # auto_now_add nadpisuje date przy create - pozycja "powstala" razem ze zleceniem.
        RepairOrderItem.objects.filter(pk=item.pk).update(created_at=order.created_at)
        touched.add(order_id)

    line = ExpressionWrapper(
        F('quantity') * F('unit_price'), output_field=DecimalField(max_digits=12, decimal_places=2),
    )
    for order_id in touched:
        total = RepairOrderItem.objects.filter(repair_order_id=order_id).aggregate(total=Sum(line))['total']
        RepairOrder.objects.filter(pk=order_id).update(final_cost=Decimal(total).quantize(Decimal('0.01')))


